```javascript
function switchAdjectiveOrder(sentence) {
  // Define a regex pattern for identifying adjectives and their positions
  const adjectivePattern = /(([A-Z][a-z]*\s)?([A-Z][a-z]+[a-z]*)(\s[a-z]+)?)/g;

  let match; // Initialize match variable
  let newSentence = ''; // Initialize new sentence variable

  while ((match = adjectivePattern.exec(sentence)) !== null) {
    // Extract the adjective and its position from the match array
    const adjPosition = sentence.indexOf(match[0]);
    const adj = match[2];

    // If it's not the first adjective, add it after the other adjectives and the article (if present)
    newSentence += sentence.slice(0, adjPosition - (match.index || 0)) +
                   (match[1] ? match[1].replace(/^[A-Z]/, ' $&') : '') + // Add article if present
                   (match[3] ? ' ' + match[3] + ' ' : '') + // Add conjunction if present
                   adj +
                   (match[4] || '') + // Add following word
                   sentence.slice(adjPosition + match[0].length); // Add remaining words
  }

  // Add the rest of the sentence if there are no more adjectives to switch
  newSentence += sentence.slice(adjectivePattern.lastIndex);

  return newSentence;
}

// Test the function
const sentence = 'Beautiful green trees are in the park';
const newSentence = switchAdjectiveOrder(sentence);
console.log(newSentence); // Output: 'Green beautiful trees are in the park'
```

