```javascript
const axios = require('axios'); // Make sure to install 'axios' package using npm or yarn before running the code

async function postMessageToSlackChannel(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.SLACK_BOT_TOKEN}`, // Replace with your bot token
      },
      data: {
        channel,
        text,
      },
    };

    const response = await axios(options);

    if (response.status === 200) {
      console.log(`Message posted successfully: ${text}`);
    } else {
      throw new Error(`Error posting message: ${JSON.stringify(response.data)}`);
    }
  } catch (error) {
    console.error(`Error posting message to Slack: ${error.message}`);
  }
}

// Usage example
postMessageToSlackChannel('Hello World!', '#general');
```

