```cpp
#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a, int b, vector<int>& seq) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }

    if (!isdigit(a + '0') || !isdigit(b + '0')) {
        throw invalid_argument("First two integers must be digits.");
    }

    if (n == 1) {
        seq.push_back(a);
        return;
    }

    fibonacci(n - 1, b, a + b, seq);
    seq.push_back(a + b);
}

int main() {
    int a, b, numElements;

    cout << "Enter the first two integers in the sequence: ";
    cin >> a >> b;

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    try {
        vector<int> sequence;
        fibonacci(numElements, a, b, sequence);

        cout << "Fibonacci sequence (" << a << ", " << b << "):";
        for (const auto& elem : sequence) {
            cout << elem << ",";
        }
        cout << endl;
    } catch (invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
    }

    return 0;
}
```

